116:/**
117: * Echter Länderinhalt je Land (Muster-Schlüssel → Freigabe-Vermerk).
118: * Nur eintragen, wenn die Seite für das Land WIRKLICH anderen, geprüften Inhalt rendert
119: * (über inhaltFuer()/landDerAnfrage(), src/lib/land/inhalte.js) – nicht nur dieselbe Seite
120: * mit anderem Präfix.
121: */
122:export const LAENDERINHALT = Object.freeze({
123:  DE: Object.freeze({
124:    "/regionen": VERMERK_DE,
125:  }),
126:  AT: Object.freeze({
127:    "/flaechencheck": VERMERK_AT,
128:    "/energiegemeinschaften": VERMERK_AT,
129:    "/regionen": VERMERK_AT,
130:  }),
131:  CH: Object.freeze({}),
132:});
