134:/** Regionsseiten: Land je Slug aus den Stammdaten der Regionen. */
135:export const REGION_LAND = Object.freeze(Object.fromEntries(REGIONEN_META.map((r) => [r.slug, r.land])));
136:
137:/** Schlüssel einer Regionsseite ("tirol" → "/regionen/tirol"). */
138:export const regionSchluessel = (slug) => "/regionen/" + slug;
139:
140:const MUSTER = Object.keys(SEITEN)
141:  .filter((k) => SEITEN[k].dynamisch)
142:  .map((k) => ({ k, basis: k.slice(0, k.indexOf("/[")) }));
143:
144:/**
145: * Pfad ohne Präfix → Registereintrag. Dynamische Seiten (/regionen/tirol) werden auf ihr Muster
146: * ("/regionen/[slug]") abgebildet; Regionen nur mit bekanntem Slug.
147: * @returns {{ schluessel: string, muster: string, eintrag: object } | null}
148: */
149:export function seiteFuer(schluesselRoh) {
150:  if (typeof schluesselRoh !== "string") return null;
151:  const schluessel = nurPfad(schluesselRoh);
152:  if (Object.hasOwn(SEITEN, schluessel) && !SEITEN[schluessel].dynamisch) return { schluessel, muster: schluessel, eintrag: SEITEN[schluessel] };
153:  for (const { k, basis } of MUSTER) {
154:    if (!schluessel.startsWith(`${basis}/`)) continue;
155:    const slug = schluessel.slice(basis.length + 1);
156:    if (!/^[a-z0-9-]+$/.test(slug)) continue;
157:    if (k === "/regionen/[slug]" && !Object.hasOwn(REGION_LAND, slug)) continue;
158:    return { schluessel, muster: k, eintrag: SEITEN[k] };
159:  }
160:  return null;
161:}
162:
163:/** Hat dieser präfixlose Pfad eine Länderfassung (/de…, /at…, /ch…)? */
164:export const hatLandfassung = (schluessel) => !!seiteFuer(schluessel);
165:
166:/** Gibt es für die Seite im Land echten, freigegebenen Länderinhalt? */
167:export function eigenerInhalt(schluessel, land) {
168:  const s = seiteFuer(schluessel);
169:  if (!s || !LAND_CODES.includes(land)) return false;
170:  return Object.hasOwn(LAENDERINHALT[land], s.muster);
171:}
172:
173:/** Länder mit eigenem Inhalt für eine Seite (LAND_CODES-Reihenfolge). */
174:export const laenderMitInhalt = (schluessel) => LAND_CODES.filter((l) => eigenerInhalt(schluessel, l));
175:
176:/**
177: * Indexierbar? land null = gemeinsame Seite (indexiert, außer index: false);
178: * Länderfassung nur mit eigenem Inhalt (sonst noindex bis zur Freigabe).
179: */
180:export function indexierbar(schluessel, land = null) {
181:  const s = seiteFuer(schluessel);
182:  if (!s || s.eintrag.index === false) return false;
183:  return land ? eigenerInhalt(schluessel, land) : true;
184:}
185:
186:/** Alle konkreten Schlüssel (Regionen aufgelöst; Ratgeber und Exposés nicht). */
187:export function alleSchluessel() {
188:  const liste = [];
189:  for (const k of Object.keys(SEITEN)) {
190:    if (k === "/regionen/[slug]") liste.push(...Object.keys(REGION_LAND).map(regionSchluessel));
191:    else if (!SEITEN[k].dynamisch) liste.push(k);
192:  }
193:  return liste;
194:}

